package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.core.BlockPos; import net.minecraft.nbt.CompoundTag; import net.minecraft.nbt.ListTag; import net.minecraft.nbt.StringTag; import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket; import net.minecraft.network.Connection; import net.minecraft.world.item.ItemStack; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.state.BlockState; import net.minecraftforge.network.NetworkHooks; import java.util.ArrayList; import java.util.List; import java.util.Set;
public final class SeasoningBottleBlockEntity extends BlockEntity { public static final int CAPACITY=8; private static final Set<String> VALID=Set.of("kaleidoscope_grilling:green_chili_powder","kaleidoscope_grilling:sichuan_pepper","kaleidoscope_grilling:onion_powder","minecraft:redstone","minecraft:gunpowder","kaleidoscope_grilling:houttuynia_powder","kaleidoscope_grilling:totem_powder","kaleidoscope_grilling:dragon_egg_powder"); private final List<String> ingredients=new ArrayList<>(); public SeasoningBottleBlockEntity(BlockPos p, BlockState s){super(ModBlockEntities.SEASONING_BOTTLE.get(),p,s);} public boolean canAdd(String id){return ingredients.size()<CAPACITY&&VALID.contains(id);} public boolean add(String id){if(!canAdd(id))return false;ingredients.add(id);sync();return true;} public List<String> ingredients(){return List.copyOf(ingredients);} public void loadFrom(ItemStack stack){ingredients.clear();ingredients.addAll(SeasoningData.get(stack));sync();} public boolean hasBase(){return ingredients.contains("kaleidoscope_grilling:green_chili_powder")&&ingredients.contains("kaleidoscope_grilling:sichuan_pepper")&&ingredients.contains("kaleidoscope_grilling:onion_powder");} private void sync(){setChanged();if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}@Override protected void saveAdditional(CompoundTag tag){super.saveAdditional(tag);write(tag);}@Override public void load(CompoundTag tag){super.load(tag);read(tag);}@Override public CompoundTag getUpdateTag(){CompoundTag tag=super.getUpdateTag();write(tag);return tag;}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(Connection net,ClientboundBlockEntityDataPacket pkt){CompoundTag tag=pkt.getTag();if(tag!=null)read(tag);}private void write(CompoundTag tag){ListTag list=new ListTag();ingredients.forEach(v->list.add(StringTag.valueOf(v)));tag.put("Ingredients",list);}private void read(CompoundTag tag){ingredients.clear();ListTag list=tag.getList("Ingredients",8);for(int i=0;i<list.size();i++)ingredients.add(list.getString(i));}}
